import {test,expect} from 'bun:test';
import {getFee,newVersion,acceptLegacyTerms,changedSinceApproval} from './subscriptions';

test('new decision is authoritative',()=>expect(getFee({terms:{},pricingDecision:{feeCents:2500}})).toBe(2500));
test('creates a version with copied terms and a fresh decision',()=>{
  const previous={terms:{monthlyFeeCents:1500,currency:'EUR'},pricingDecision:{feeCents:1500}};
  expect(newVersion(previous,{feeCents:2500,decidedAt:'2026-11-02'})).toEqual({
    terms:{monthlyFeeCents:1500,currency:'EUR'},
    pricingDecision:{feeCents:2500,decidedAt:'2026-11-02'},
  });
});
test('new versions require a valid fee decision',()=>{
  expect(()=>newVersion({terms:{}},undefined)).toThrow();
  expect(()=>newVersion({terms:{}},{feeCents:-1})).toThrow();
});
test('legacy terms remain accepted and fee changes are detected',()=>{
  expect(acceptLegacyTerms({monthlyFeeCents:200})).toEqual({monthlyFeeCents:200});
  expect(changedSinceApproval({terms:{monthlyFeeCents:1500},pricingDecision:{feeCents:2500}})).toBe(true);
});

