export const MIN_FEE = 100;

export function getFee(subscription: any): number {
  return subscription.pricingDecision?.feeCents ?? MIN_FEE;
}

/** Create the next version while retaining its existing terms and recording
 * the fresh fee decision required for that version. */
export function newVersion(previous: any, feeDecision: any) {
  if (!feeDecision || !Number.isInteger(feeDecision.feeCents) || feeDecision.feeCents < 0) {
    throw new Error('a valid fee decision is required');
  }
  return {
    terms: { ...previous.terms },
    pricingDecision: { ...feeDecision },
  };
}

export function changedSinceApproval(subscription: any): boolean {
  return getFee(subscription) !== subscription.terms.monthlyFeeCents;
}

// Legacy clients continue to submit monthlyFeeCents in terms.
export function acceptLegacyTerms(input: any) {
  if (!Number.isInteger(input.monthlyFeeCents)) throw new Error('invalid');
  return input;
}
